package com.axiom.analysis.classification;
import com.axiom.domain.evidence.EvidenceSeverity; import com.axiom.domain.failure.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class ExplainableFailureClassifier {
 public Result classify(String message,String exception){String s=(message+" "+Optional.ofNullable(exception).orElse("")).toLowerCase();List<ClassificationEvidence> e=new ArrayList<>();add(e,s,"outofmemory|java heap space|no space left|enospace","RESOURCE_EXHAUSTION","RESOURCE_EXHAUSTED",EvidencePriority.ROOT_SIGNAL,.9);add(e,s,"connection refused|connection reset|unknownhost|network unreachable","INFRASTRUCTURE_FAILURE","NETWORK_CONNECTION_FAILURE",EvidencePriority.ROOT_SIGNAL,.85);add(e,s,"could not resolve|artifact not found|dependency could not","DEPENDENCY_FAILURE","DEPENDENCY_RESOLUTION_FAILED",EvidencePriority.ROOT_SIGNAL,.85);add(e,s,"cannot find symbol|incompatible types|compilation failure","BUILD_FAILURE","COMPILATION_FAILED",EvidencePriority.ROOT_SIGNAL,.85);add(e,s,"assertionerror|assertion failed|expected:<","TEST_FAILURE","TEST_ASSERTION_FAILED",EvidencePriority.ROOT_SIGNAL,.85);add(e,s,"timed out|timeout","TIMEOUT","TIMEOUT_DETECTED",EvidencePriority.PRIMARY,.75);add(e,s,"missing environment variable|required setting missing|configuration property.*not found","CONFIGURATION_FAILURE","CONFIGURATION_MISSING",EvidencePriority.ROOT_SIGNAL,.85);add(e,s,"exit code|build failed|command failed","BUILD_FAILURE","COMMAND_FAILED",EvidencePriority.DOWNSTREAM,.25);Map<FailureClassification,Double> scores=new EnumMap<>(FailureClassification.class);for(var x:e)scores.merge(x.category(),x.weight()*multiplier(x.priority()),Double::sum);var top=scores.entrySet().stream().max(Map.Entry.comparingByValue()).orElse(null);FailureClassification c=top==null||top.getValue()<.4?FailureClassification.UNKNOWN:top.getKey();double confidence=top==null?0:Math.min(1,top.getValue());return new Result(c,confidence,level(confidence,c),e.stream().filter(x->x.category()==c).toList());}
 private void add(List<ClassificationEvidence> e,String s,String regex,String c,String code,EvidencePriority p,double w){if(s.matches("(?s).*?("+regex+").*"))e.add(new ClassificationEvidence(code,code.replace('_',' ').toLowerCase(),FailureClassification.valueOf(c),EvidenceSeverity.HIGH,p,w,"axiom-classifier-v1"));} private double multiplier(EvidencePriority p){return switch(p){case ROOT_SIGNAL->1;case PRIMARY->.8;case SECONDARY->.5;case DOWNSTREAM->.2;};}private ConfidenceLevel level(double c,FailureClassification x){if(x==FailureClassification.UNKNOWN)return ConfidenceLevel.UNKNOWN;return c>=.8?ConfidenceLevel.HIGH:c>=.6?ConfidenceLevel.MEDIUM:ConfidenceLevel.LOW;} public record Result(FailureClassification classification,double confidence,ConfidenceLevel level,List<ClassificationEvidence> evidence){}
}
